const post=async(u,q,v)=>{const r=await fetch(u,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query:q,variables:v})});return r.json()};
const tn=t=>t.name||(t.ofType&&tn(t.ofType));
const intro=async(u,t)=>{const j=await post(u,`{__type(name:"${t}"){kind possibleTypes{name} enumValues{name} inputFields{name type{name kind ofType{name kind ofType{name}}}} fields{name type{name kind ofType{name kind ofType{name}}}}}}`);const x=j.data&&j.data.__type;if(!x)return JSON.stringify(j).slice(0,300);return x.kind+": "+((x.fields||x.inputFields||[]).map(f=>f.name+":"+tn(f.type)).join(" | ")||"")+(x.possibleTypes?" types="+x.possibleTypes.map(p=>p.name).join(","):"")+(x.enumValues?" enum="+x.enumValues.map(p=>p.name).join(","):"")};
const A="https://api.v3.aave.com/graphql",M="https://api.morpho.org/graphql";
for(const t of ["MarketsRequest","ChainMarketsRequest","SupplyRequest","SupplyAmountInput","AmountInput","WithdrawRequest","WithdrawAmountInput","ExecutionPlan","TransactionRequest","ApprovalRequired","InsufficientBalanceError","UserSuppliesRequest","UserSuppliesFilter","MarketInput","Currency","TokenAmount","DecimalValue","PercentValue","NativeCurrency","ReserveSupplyInfo","Chain","ChainsFilter","Erc20Amount","NativeAmount","Erc20ApprovalRequired","PermitRequest","SignatureInput","ERC712Signature","Erc712Signature"])console.log("AAVE",t,"=>",await intro(A,t));
const mq=await post(M,`{vaults(first:5,orderBy:TotalAssetsUsd,orderDirection:Desc,where:{chainId_in:[8453],whitelisted:true}){items{address name symbol chain{id} asset{address symbol decimals priceUsd logoURI} state{netApy apy fee totalAssetsUsd} metadata{curators{name}}}}}`);
console.log("MORPHO v1",JSON.stringify(mq).slice(0,2500));
const m2=await post(M,`{vaultV2s(first:5,where:{chainId_in:[8453]}){items{address name symbol chain{id} asset{address symbol decimals} totalAssetsUsd avgNetApy netApy performanceFee managementFee whitelisted curator{address} }}}`);
console.log("MORPHO v2",JSON.stringify(m2).slice(0,2500));
const u=await post(M,`{userByAddress(address:"0x2c1d52c1bfdbd6a4e43dce4dd3a3fda3fb8b3a0b",chainId:8453){vaultPositions{vault{address} state{assets assetsUsd shares}} vaultV2Positions{vault{address} assets assetsUsd shares}}}`);
console.log("MORPHO user",JSON.stringify(u).slice(0,1500));
